import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
DC = ROOT / "deli_counter"
PINS = {'hole_causes.py': '2e5f8389cd7caaf3', 'presets.py': '001a5ebbbb2266f7', 'new_level.py': 'b9902e2d6308694f', 'test_hole_causes.py': '5dbf3a4e67f7bf73', 'specs/deli_a01.json': '72b162e3288e85cb'}
EDITS = {'hole_causes.py': [('lines 154-153', '    return [v for v in spec.get("vertical_links") or [] if is_drop(spec, v)]\n\n', '    return [v for v in spec.get("vertical_links") or [] if is_drop(spec, v)]\n\n\ndef without_holes(spec):\n    """Leave out every hole in a floor a player would see, in place: ``(links, slab_holes)`` removed.\n\n    A HOLE IS AN OPTIONAL ROUTE (0.237.0, the factory\'s roadmap 269). The walker, 2026-10-20: "stairs and ladders\n    should be the primary way to get between floors in this game...with the holes in floors being somewhat rare...but\n    still at our disposal". A drop (`is_drop`) goes, unless it opens into a stair\'s own well (`cause_for` says\n    `stair`: nothing of it shows, and the stair is the route there anyway). So do the authored ``slab_holes`` whose\n    plan overlaps a removed drop\'s hole on ANY storey -- a recipe authors the slab hole beside the link, and an\n    atrium or a shaft cuts every storey it passes through while its link names one; left behind, a slab hole is an\n    undeclared drop. A roof hatch is not a hole in a floor (`is_drop`), and a stair or a ladder is not touched."""\n    links, keep = [], []\n    for v in spec.get("vertical_links") or []:\n        (links if is_drop(spec, v) and cause_for(spec, v) != STAIR else keep).append(v)\n    if not links:\n        return [], []\n    spec["vertical_links"] = keep\n    rects = [_rect(v) for v in links]\n    holes, left = [], []\n    for h in spec.get("slab_holes") or []:\n        (holes if any(_overlaps(_rect(h), r) for r in rects) else left).append(h)\n    if "slab_holes" in spec:\n        spec["slab_holes"] = left\n    return links, holes\n\n')], 'presets.py': [('lines 3821-3821', '         **kwargs) -> dict:\n', '         holes: Optional[bool] = None, **kwargs) -> dict:\n'), ('lines 3846-3846', '    this point and proves the result across 100 seeds per preset."""\n', '    this point and proves the result across 100 seeds per preset.\n\n    `holes=False` builds the recipe without the holes in its floors a player\n    would see (0.237.0, the factory\'s roadmap 269; `hole_causes.without_holes`):\n    stairs and ladders are the way between floors, and a hole is an optional\n    route Level Factory asks for on some levels. None, and True, build what the\n    recipe authored."""\n'), ('lines 3851-3850', '    spec = REGISTRY[preset](**kwargs)\n    # NO PIECE THROUGH A WALL (0.199.0): a piece a recipe authors through one\n', '    spec = REGISTRY[preset](**kwargs)\n    # A HOLE IS AN OPTIONAL ROUTE (0.237.0): left out here, before every pass\n    # below, so the cover, the stairs and the furniture are placed in a floor\n    # that never had it.\n    if holes is False:\n        import hole_causes\n        hole_causes.without_holes(spec)\n    # NO PIECE THROUGH A WALL (0.199.0): a piece a recipe authors through one\n')], 'new_level.py': [('lines 85-84', '                         "different building (see stair_regression.py)")\n    ap.add_argument("--list", action="store_true", help="list available presets and exit")\n', '                         "different building (see stair_regression.py)")\n    ap.add_argument("--holes", choices=("on", "off"), default=None,\n                    help="off builds the recipe without the holes in its floors a player "\n                         "would see (an optional route; the stairs and ladders stay); "\n                         "on, or unset, builds what the recipe authored")\n    ap.add_argument("--list", action="store_true", help="list available presets and exit")\n'), ('lines 119-118', '        kwargs["seed"] = args.seed\n\n', '        kwargs["seed"] = args.seed\n    if args.holes is not None:\n        kwargs["holes"] = args.holes == "on"\n\n')], 'test_hole_causes.py': [('lines 306-306', '    """0.235.0\'s library: 21 drop links in 12 specs. The six delis\' hideout floors (concrete) cut through to their\n', '    """0.235.0\'s library: 21 drop links in 12 specs -- 20 in 12 since 0.237.0, deli_a01\'s cut left out (below). The\n    six delis\' hideout floors (concrete) cut through to their\n'), ('lines 323-323', '    assert got == {"corner_deli_heist_01": deli, "cr_deli": deli, "deli_a01": cut, "deli_a02": cut,\n', '    # deli_a01 carries no drop since 0.237.0 (`migrate_hole_free_variants.py`): the deli family keeps one\n    # variant a themed lot can draw without a hole (test_optional_holes.py).\n    assert got == {"corner_deli_heist_01": deli, "cr_deli": deli, "deli_a02": cut,\n')], 'specs/deli_a01.json': [('lines 457-465', ' "slab_holes": [\n  {\n   "story": 1,\n   "x": 8.5,\n   "y": -4.0,\n   "size_x": 2.2,\n   "size_y": 2.2\n  }\n ],\n', ' "slab_holes": [],\n'), ('lines 472-480', '  },\n  {\n   "kind": "floor_hole",\n   "story": 1,\n   "x": 8.5,\n   "y": -4.0,\n   "size_x": 2.2,\n   "size_y": 2.2,\n   "role": "vertical_attack_angle"\n', '')]}
NEW_FILES = {'test_optional_holes.py': '"""A hole in a floor is an optional route, left out when asked (0.237.0; the factory\'s roadmap 269).\n\nThe walker, 2026-10-20: "stairs and ladders should be the primary way to get between floors in this game...with the\nholes in floors being somewhat rare...but still at our disposal to use if needed/desired to add some more ways to\nnavigate levels". Measured before this (the factory\'s `docs/findings/hole_frequency/`): every corner-deli level carried\nthe deli\'s cut drop -- both of the deli family\'s themeable variants had one -- and every single-building deli and\ncounty-hospital level carried its preset\'s.\n\n`hole_causes.without_holes` leaves out every drop a player would see -- a floor hole, a hatch below the roof -- and the\nauthored slab holes under it, and keeps a drop that opens into a stair\'s own well (nothing of it shows). `presets.make`\ntakes `holes=False` to build without them, which Level Factory asks for on the levels its rate leaves without one;\n`holes=None` (and True) builds what the recipe authored, as always. And the deli family keeps a variant without the\ndrop (`migrate_hole_free_variants.py`: deli_a01), so a lot can be drawn without one.\n\nFAIL ON 0.236.1: there is no `without_holes`, `presets.make` refuses `holes`, and deli_a01 carries the cut drop.\n"""\nimport json\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport hole_causes as HC             # noqa: E402\nimport presets                       # noqa: E402\n\n#: The presets that author a drop a player would see, each with the role it gives it.\nDROP_PRESETS = {"police_station": None, "corner_deli": "vertical_attack_angle",\n                "compound": "atrium_vertical_sightline", "hospital": "elevator_shaft_horde_channel",\n                "casino_tower": "count_room_skylight"}\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _seen(spec):\n    """The drops a player would see: `is_drop`, cause not `stair`."""\n    return [v for v in HC.drop_links(spec) if HC.cause_for(spec, v) != HC.STAIR]\n\n\ndef _under(spec, links):\n    """The authored slab holes whose plan overlaps any of `links`\' holes, on any storey."""\n    rects = [HC._rect(v) for v in links]\n    return [h for h in spec.get("slab_holes") or [] if any(HC._overlaps(HC._rect(h), r) for r in rects)]\n\n\ndef test_without_holes_leaves_out_the_drop_and_the_slab_hole_under_it():\n    spec = {"name": "t", "n_stories": 3, "story_height": 3.2, "footprint_x": 20.0, "footprint_y": 16.0,\n            "vertical_links": [{"kind": "stair", "from_story": 0, "to_story": 2},\n                               {"kind": "floor_hole", "story": 1, "x": -5.0, "y": 0.0, "size_x": 2.2, "size_y": 2.2},\n                               {"kind": "hatch", "story": 3, "x": 4.0, "y": 4.0}],\n            "slab_holes": [{"story": 1, "x": -5.0, "y": 0.0, "size_x": 2.2, "size_y": 2.2},\n                           {"story": 2, "x": -5.0, "y": 0.0, "size_x": 1.0, "size_y": 1.0},\n                           {"story": 1, "x": 6.0, "y": -6.0, "size_x": 1.0, "size_y": 1.0}]}\n    links, holes = HC.without_holes(spec)\n    assert [v["kind"] for v in links] == ["floor_hole"]\n    # the slab holes over the drop go with it, on every storey (an atrium, a shaft); another stays\n    assert holes == [{"story": 1, "x": -5.0, "y": 0.0, "size_x": 2.2, "size_y": 2.2},\n                     {"story": 2, "x": -5.0, "y": 0.0, "size_x": 1.0, "size_y": 1.0}]\n    assert spec["slab_holes"] == [{"story": 1, "x": 6.0, "y": -6.0, "size_x": 1.0, "size_y": 1.0}]\n    # the stair and the roof hatch are not holes in a floor\n    assert [v["kind"] for v in spec["vertical_links"]] == ["stair", "hatch"]\n    assert HC.without_holes(spec) == ([], [])\n\n\ndef test_a_drop_into_a_stairs_own_well_stays():\n    """deli_a03\'s hatch opens into its stair\'s well: nothing of it shows, so it is not a hole to leave out."""\n    spec = _spec("deli_a03")\n    well = [v for v in HC.drop_links(spec) if HC.cause_for(spec, v) == HC.STAIR]\n    assert len(well) == 1\n    links, _holes = HC.without_holes(spec)\n    assert [v.get("role") for v in links] == ["vertical_attack_angle"]\n    assert well[0] in spec["vertical_links"]\n\n\n@pytest.mark.parametrize("preset", sorted(DROP_PRESETS))\ndef test_a_preset_builds_without_its_holes_when_asked(preset):\n    authored = presets.make(preset)\n    seen = _seen(authored)\n    assert seen and DROP_PRESETS[preset] in [v.get("role") for v in seen]\n    assert presets.make(preset, holes=True) == authored          # True is what the recipe authored\n    left = presets.make(preset, holes=False)\n    assert _seen(left) == []\n    assert _under(left, seen) == []                               # no slab hole left where a drop was\n    # nothing else moved out of the vertical links\n    assert [v for v in left["vertical_links"] if v not in seen] == left["vertical_links"]\n\n\ndef test_a_preset_without_a_hole_is_unchanged_by_the_flag():\n    assert presets.make("bank", holes=False) == presets.make("bank")\n\n\ndef test_the_deli_family_keeps_a_variant_without_the_drop():\n    """deli_a01 and deli_a03 are the two delis a themed lot can draw; one of them now has no hole to see."""\n    assert _seen(_spec("deli_a01")) == []\n    assert _under(_spec("deli_a01"), [{"x": 8.5, "y": -4.0, "size_x": 2.2, "size_y": 2.2}]) == []\n    assert [v.get("role") for v in _seen(_spec("deli_a03"))] == ["vertical_attack_angle"]\n\n\ndef test_the_migration_is_done_and_idempotent():\n    import migrate_hole_free_variants as M\n    assert M.HOLE_FREE == ("deli_a01",)\n    assert M.main(["--check"]) == 0\n', 'migrate_hole_free_variants.py': '#!/usr/bin/env python3\n"""\nmigrate_hole_free_variants.py  --  a family\'s variant without a hole in its floor\n=================================================================================\nOne-shot, idempotent migration for the factory\'s roadmap 269. The walker,\n2026-10-20: "stairs and ladders should be the primary way to get between floors\nin this game...with the holes in floors being somewhat rare...but still at our\ndisposal to use if needed/desired to add some more ways to navigate levels".\n\nLevel Factory draws a level without a hole by swapping a lot\'s building for a\nvariant of its family that has none -- and the deli family had no such variant\na themed lot could draw: deli_a01 and deli_a03 both carried the 2.2 m cut drop\nfrom the apartment hideout into the kitchen (deli_a02 is not themeable). So\nevery corner-deli level carried one (the factory\'s\n`docs/findings/hole_frequency/`).\n\nEach spec in HOLE_FREE loses the holes in its floors a player would see\n(`hole_causes.without_holes`: the drop link and the authored slab hole under\nit; a hatch into the stair\'s own well stays) and is REFURNISHED, so it stays a\nfixed point of furnish (`test_club_fixtures`): the hideout\'s floor where the\nhole was is floor again, and furnish lays a room round what stands in it.\n\n    python migrate_hole_free_variants.py            # write specs/\n    python migrate_hole_free_variants.py --check    # report only; exit 1 if any would change\n"""\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport hole_causes               # noqa: E402\nimport migrate_furnish_recipes   # noqa: E402\n\n#: The variants that carry no hole. A call, made 2026-10-20 and meant to be\n#: changed: deli_a01, because deli_a03 keeps the drop the factory\'s cold runs\n#: 9340 and 9341 proved and priced.\nHOLE_FREE = ("deli_a01",)\n\n\ndef migrate(d):\n    """Leave out one spec dict\'s holes and refurnish it, in place: ``(links, slab_holes)`` removed."""\n    links, holes = hole_causes.without_holes(d)\n    if links:\n        migrate_furnish_recipes.migrate(d)\n    return links, holes\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    changed = []\n    for name in HOLE_FREE:\n        p = os.path.join(HERE, "specs", name + ".json")\n        d = json.load(open(p, encoding="utf-8"))\n        links, holes = migrate(d)\n        if not links:\n            continue\n        changed.append((name, links, holes))\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    for name, links, holes in changed:\n        print("  %s: %s, %d slab hole(s)" % (\n            name, ", ".join("%s %s at (%g, %g)" % (v.get("kind"), v.get("role") or "", float(v["x"]), float(v["y"]))\n                            for v in links), len(holes)))\n    print("[hole_free_variants] %d spec(s) %s" % (len(changed), "to change" if check else "changed"))\n    return 1 if (check and changed) else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'}
CHANGELOG = '## [0.237.0] - a hole in a floor is an optional route: left out on request, and the deli family keeps a variant without one\n\n**The factory\'s roadmap 269.** The walker, 2026-10-20: "stairs and ladders should be the primary way to get between\nfloors in this game...with the holes in floors being somewhat rare...but still at our disposal to use if\nneeded/desired to add some more ways to navigate levels". Measured first (the factory\'s\n`docs/findings/hole_frequency/`, a level-by-level replay of Level Factory\'s own lot draw): across the 24 staged lot\nmissions 54 of 288 levels carried a hole a player sees, and they bunched where a family that always carries one\nanchors the mission -- every restaurant_row_001 and urban_row_001 level had the deli\'s cut drop, because both of the\ndeli variants a themed lot can draw (deli_a01, deli_a03) carry it -- and every single-building level whose preset\nauthors one (deli_001\'s cut and hatch; county_hospital_001\'s elevator shafts, bare). Level Factory decides per level\nwhether one is wanted; this release gives it the two things it needs from here.\n\n### Added\n- `hole_causes.without_holes(spec)`: leaves out, in place, every drop a player would see -- `is_drop`, unless it\n  opens into a stair\'s own well (`cause_for` says `stair`: nothing of it shows) -- and the authored `slab_holes`\n  whose plan overlaps a removed drop\'s hole on ANY storey, because a recipe authors the slab hole beside the link\n  and an atrium or a shaft cuts every storey its one link passes; a slab hole left behind is an undeclared drop. A\n  roof hatch, a stair and a ladder are untouched. Returns what it removed.\n- `presets.make(..., holes=None)`: `False` builds the recipe without them, right after the recipe returns and before\n  every other pass, so cover, stairs and furniture are placed in a floor that never had the hole. None and True build\n  what the recipe authored, as always. The five presets that author one: police_station (the armory\'s floor hatch),\n  corner_deli (the hideout\'s cut drop), compound (the atrium), hospital (the elevator shafts), casino_tower (the\n  count room\'s skylight).\n- `new_level.py --holes on|off`, passed through to it.\n- `migrate_hole_free_variants.py`: the variants in `HOLE_FREE` lose their holes and are refurnished, so each stays a\n  fixed point of furnish. **A call, made 2026-10-20 and meant to be changed: deli_a01**, because deli_a03 keeps the\n  drop the factory\'s cold runs 9340 and 9341 proved and priced. Run once: deli_a01 lost its 2.2 m drop at (8.5, -4)\n  and the slab hole under it; its hatch into the stair\'s well stays; the refurnish moved nothing.\n\n### Tests\n- `test_optional_holes.py` (10; every one fails on 0.236.1): the drop and the slab holes under it on every storey go\n  and another slab hole stays; a hatch into a stair\'s well stays (deli_a03); each of the five presets builds without\n  its holes when asked and with them otherwise, `holes=True` equal to the recipe; a preset with no hole is unchanged;\n  the deli family keeps a variant without the drop and one with it; the migration is done and idempotent.\n- `test_hole_causes.py`\'s library test: deli_a01 no longer dresses a hole (20 drop links in 12 specs).\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.236.1', 'Deli Counter 0.237.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    raw = (DC / name).read_bytes()
    if _sha(raw) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing written"
                         % (name, _sha(raw), PINS[name]))
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: deli_counter/%s has CRLF endings; these edits are LF" % name)
    return raw.decode("utf-8")


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text
    for name in NEW_FILES:
        p = DC / name
        if p.exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = DC / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = DC / "CHANGELOG.md"
    ctext = cl.read_bytes().decode("utf-8")
    if not ctext.startswith("## [0.236.1]"):
        raise SystemExit("REFUSED: CHANGELOG.md does not open on 0.236.1; nothing written")
    for name, text in out.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes((CHANGELOG + ctext).encode("utf-8"))
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: the suite, "
          "build.py --all, check.py" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
